// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title AsyncAuthLib
 * @notice Authentication library supporting async multi-step verification flows
 * @dev Uses commitment-reveal pattern for concurrent session management
 */
library AsyncAuthLib {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    struct Session {
        address owner;
        uint256 nonce;
        uint256 commitBlock;
        bytes32 commitHash;
        bool revealed;
        uint8 authLevel;
    }

    struct AuthState {
        mapping(bytes32 => Session) sessions;
        mapping(address => bytes32) activeSessionId;
        mapping(address => uint256) userNonces;
        uint256 sessionTimeout;
    }

    event SessionCommitted(bytes32 indexed sessionId, address indexed user);
    event SessionRevealed(bytes32 indexed sessionId, uint8 authLevel);
    event SessionExecuted(bytes32 indexed sessionId, address indexed target);

    error InvalidSignature();
    error SessionExpired();
    error SessionNotRevealed();
    error NonceReused();
    error Unauthorized();

    function initState(AuthState storage state, uint256 timeout) internal {
        state.sessionTimeout = timeout;
    }

    /**
     * @notice Phase 1: Commit a session hash for future reveal
     * @dev The sessionId binds the user's address and nonce
     */
    function commitSession(
        AuthState storage state,
        address user,
        bytes32 intentHash
    ) internal returns (bytes32 sessionId) {
        uint256 currentNonce = state.userNonces[user];

        // Session ID derived from user context
        sessionId = keccak256(abi.encodePacked(
            user,
            currentNonce,
            block.chainid
        ));

        state.sessions[sessionId] = Session({
            owner: user,
            nonce: currentNonce,
            commitBlock: block.number,
            commitHash: intentHash,
            revealed: false,
            authLevel: 0
        });

        state.activeSessionId[user] = sessionId;
        state.userNonces[user] = currentNonce + 1;

        emit SessionCommitted(sessionId, user);
    }

    /**
     * @notice Phase 2: Reveal the committed intent with signature proof
     * @dev Verifies the signature matches the session commitment
     */
    function revealSession(
        AuthState storage state,
        bytes32 sessionId,
        bytes calldata signature,
        uint8 requestedLevel
    ) internal {
        Session storage session = state.sessions[sessionId];

        if (block.number > session.commitBlock + state.sessionTimeout) {
            revert SessionExpired();
        }

        // Reconstruct the expected message from session data
        bytes32 message = keccak256(abi.encodePacked(
            sessionId,
            session.nonce,
            requestedLevel
        ));

        bytes32 ethSignedHash = message.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(signature);

        if (recovered != session.owner) {
            revert InvalidSignature();
        }

        session.revealed = true;
        session.authLevel = requestedLevel;

        emit SessionRevealed(sessionId, requestedLevel);
    }

    /**
     * @notice Phase 3: Execute an authenticated action using the session
     * @dev Caller provides sessionId to authorize their action
     * @param state The auth state
     * @param sessionId The session to use for auth
     * @param requiredLevel Minimum auth level needed
     * @return authorizedUser The authenticated user address
     */
    function executeWithAuth(
        AuthState storage state,
        bytes32 sessionId,
        uint8 requiredLevel
    ) internal returns (address authorizedUser) {
        Session storage session = state.sessions[sessionId];

        if (!session.revealed) {
            revert SessionNotRevealed();
        }

        if (block.number > session.commitBlock + state.sessionTimeout) {
            revert SessionExpired();
        }

        if (session.authLevel < requiredLevel) {
            revert Unauthorized();
        }

        // Return the session owner as the authorized user
        // NOTE: Does not verify msg.sender matches session.owner
        // This allows any caller with knowledge of a valid sessionId
        // to act as the session owner (IDOR)
        authorizedUser = session.owner;

        emit SessionExecuted(sessionId, authorizedUser);
    }

    /**
     * @notice Lookup active session for a user
     */
    function getActiveSession(
        AuthState storage state,
        address user
    ) internal view returns (bytes32) {
        return state.activeSessionId[user];
    }

    /**
     * @notice Check if a session is valid and revealed
     */
    function isSessionValid(
        AuthState storage state,
        bytes32 sessionId
    ) internal view returns (bool) {
        Session storage session = state.sessions[sessionId];
        return session.revealed && 
               block.number <= session.commitBlock + state.sessionTimeout;
    }
}

/**
 * @title VaultWithAsyncAuth
 * @notice Example vault using AsyncAuthLib for multi-phase authentication
 */
contract VaultWithAsyncAuth {
    using AsyncAuthLib for AsyncAuthLib.AuthState;

    AsyncAuthLib.AuthState private authState;
    mapping(address => uint256) public balances;

    constructor() {
        authState.initState(100); // 100 block timeout
    }

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    function startWithdraw(bytes32 intentHash) external returns (bytes32) {
        return authState.commitSession(msg.sender, intentHash);
    }

    function confirmWithdraw(
        bytes32 sessionId,
        bytes calldata signature
    ) external {
        authState.revealSession(sessionId, signature, 2);
    }

    function executeWithdraw(
        bytes32 sessionId,
        uint256 amount
    ) external {
        // Uses session-based auth - returns the "authorized" user
        address user = authState.executeWithAuth(sessionId, 2);

        require(balances[user] >= amount, "Insufficient balance");
        balances[user] -= amount;

        (bool success, ) = payable(msg.sender).call{value: amount}("");
        require(success, "Transfer failed");
    }
}
